using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;

namespace MyApp.Filters
{
    public class RequireHttpsAttribute : Attribute, IAuthorizationFilter
    {
        public void OnAuthorization(AuthorizationFilterContext context)
        {
            if (!context.HttpContext.Request.IsHttps)
            {
                context.Result = new StatusCodeResult(StatusCodes.Status403Forbidden);
            }
        }
    }
}

using Microsoft.AspNetCore.Mvc.Filters;
using System.Diagnostics;

namespace MyApp.Filters
{
    public class TimeElapsedAttribute : Attribute, IActionFilter
    {
        private Stopwatch _stopwatch;

        public void OnActionExecuting(ActionExecutingContext context)
        {
            _stopwatch = Stopwatch.StartNew();
        }

        public void OnActionExecuted(ActionExecutedContext context)
        {
            _stopwatch.Stop();
            var elapsed = $"Elapsed: {_stopwatch.Elapsed.TotalMilliseconds:F2} ms";
            if (context.Result is ObjectResult objectResult)
            {
                objectResult.Value = $"{objectResult.Value} | {elapsed}";
            }
        }
    }
}

using Microsoft.AspNetCore.Mvc.Filters;
using System.Diagnostics;

namespace MyApp.Filters
{
    public class TimeElapsedAsyncAttribute : Attribute, IAsyncActionFilter
    {
        public async Task OnActionExecutionAsync(
            ActionExecutingContext context,
            ActionExecutionDelegate next)
        {
            var stopwatch = Stopwatch.StartNew();
            var executedContext = await next();
            stopwatch.Stop();
            var elapsed = $"Elapsed: {stopwatch.Elapsed.TotalMilliseconds:F2} ms";
            if (executedContext.Result is ObjectResult objectResult)
            {
                objectResult.Value = $"{objectResult.Value} | {elapsed}";
            }
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;

namespace MyApp.Filters
{
    public class ChangeViewAttribute : Attribute, IResultFilter
    {
        public void OnResultExecuting(ResultExecutingContext context)
        {
            if (context.Result is ViewResult viewResult)
            {
                viewResult.ViewName = "AlternateView";
            }
        }

        public void OnResultExecuted(ResultExecutedContext context)
        {
            // Runs after the result has been processed
        }
    }
}

using Microsoft.AspNetCore.Mvc.Filters;

namespace MyApp.Filters
{
    public class ChangeViewAsyncAttribute : Attribute, IAsyncResultFilter
    {
        public async Task OnResultExecutionAsync(
            ResultExecutingContext context,
            ResultExecutionDelegate next)
        {
            if (context.Result is ViewResult viewResult)
            {
                viewResult.ViewName = "AlternateView";
            }
            await next();
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace MyApp.Filters
{
    public class CatchErrorAttribute : Attribute, IExceptionFilter
    {
        public void OnException(ExceptionContext context)
        {
            context.Result = new ViewResult
            {
                ViewData = new ViewDataDictionary(
                    new EmptyModelMetadataProvider(),
                    new ModelStateDictionary())
                {
                    Model = context.Exception.Message
                }
            };
            context.ExceptionHandled = true;
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using System.Diagnostics;

namespace MyApp.Filters
{
    public class HybridTimerAttribute : ActionFilterAttribute
    {
        private Stopwatch _stopwatch;

        public override async Task OnActionExecutionAsync(
            ActionExecutingContext context,
            ActionExecutionDelegate next)
        {
            _stopwatch = Stopwatch.StartNew();
            await next();
        }

        public override async Task OnResultExecutionAsync(
            ResultExecutingContext context,
            ResultExecutionDelegate next)
        {
            _stopwatch.Stop();
            context.Result = new ViewResult
            {
                ViewName = "ElapsedTime",
                ViewData = new ViewDataDictionary(
                    new EmptyModelMetadataProvider(),
                    new ModelStateDictionary())
                {
                    Model = $"Elapsed: {_stopwatch.Elapsed.TotalMilliseconds:F2} ms"
                }
            };
            await next();
        }
    }
}
